```js
function launchHomingBullet(boss, typeId) {
  const head = boss.getHeadLocation()
  const target = findBossTarget(boss)
  if (!target) return
  let dir = normalize(target.location+1y - head)  // aim at body
  spawn bullet at head + dir*1.5
  setProjectileOwner(bullet, boss)
  let velocity = dir * BULLET_SPEED
  setBallVelocity(bullet, velocity)
  let ticks = 0
  let lastPos = bullet.location
  const runId = system.runInterval(() => {
    if (!isAlive(bullet)) { clearRun; finish(id, lastPos, dim) ... }
    ticks += 2
    lastPos = bullet.location
    if (ticks <= BULLET_HOMING_TICKS) {
      let t = isAlive(target) ? target : findBossTarget(boss)
      if (t) steer: blend velocity dir toward (t.location+1y - pos), normalize, * BULLET_SPEED
    }
    setBallVelocity(bullet, velocity)
  }, 2)
}
```
