{"content": "/**
 * 天穹探寻者（lucky:unseeker_boss）—— 斗兽场级空中 Boss。
 *
 * 素材与阶段机改自《动漫忍术》Add-On 的 unseeker（建模/动画/音效/粒子归原作者），
 * 行为按本地图法杖体系重写：
 *  - 天空阶段：悬浮游走，每 12 秒一轮弹幕（炸弹球/冰球交替），打完 3 轮（红血 4 轮）后降落；
 *  - 降落阶段：俯冲落地 → 冲击波（半径 6，16 伤害 + 击飞）→ 冥想爆发（找最近的至多 3 名
 *    玩家各来一次 18 伤害的爆炸冲击，半径 4）→ 起飞回到天空；
 *  - 追踪弹：照抄爆炸法杖炸弹球 / 冰法杖冰弹的实体 JSON 与脚本收尾架构
 *    （引擎 on_hit 判定 + scriptevent 通知 + Set 去重 + lastPos 补炸），
 *    追踪强度加强到潜影贝子弹级别（每 2 tick 速度方向朝目标混合 50%，速率恒定），
 *    目标只锁玩家（天然避开地图装饰实体的假目标问题）。
 *
 * 引擎判定、脚本收尾的分工与 staffs.js 完全一致：boss 的 BP 事件只负责排程与动画，
 * 这里负责出手、追踪、结算与音画反馈。
 */
import {
    world,
    system,
    ItemStack,
    EntityDamageCause,
    EntityProjectileComponent,
    TicksPerSecond,
} from "@minecraft/server";

const PROJECTILE_COMPONENT = EntityProjectileComponent.componentId;

const BOSS_TYPE = "lucky:unseeker_boss";
const BOMB_BULLET = "lucky:boss_bomb_bullet";
const ICE_BULLET = "lucky:boss_ice_bullet";

/** 追踪弹的飞行速率（格/tick），炸弹弹 0.9 / 冰弹 1.0。 */
const BULLET_SPEED_BOMB = 0.9;
const BULLET_SPEED_ICE = 1.0;
/**
 * 追踪强度：每 2 tick 把速度方向朝目标方向混合 50%（速率不变）。
 * 冰法杖是 0.3 的“弱追踪”，boss 弹加强到 0.5 —— 转弯半径极小，
 * 直线跑不掉、必须借助掩体或走位甩尾，即潜影贝子弹那种贴身咬人的感觉。
 */
const BULLET_STEER = 0.5;
/** 追踪持续时间（tick）：5 秒后停止修正改为直飞，避免无限追人。 */
const BULLET_HOMING_TICKS = 5 * TicksPerSecond;
/** 弹幕内相邻两发子弹的间隔（tick）。 */
const VOLLEY_GAP_TICKS = 8;
/** 一轮炸弹弹幕的子弹数（红血阶段再 +1）。 */
const VOLLEY_BOMB_COUNT = 3;
/** 一轮冰弹幕的子弹数（红血阶段再 +1）。 */
const VOLLEY_ICE_COUNT = 4;
/** boss 索敌半径：只锁玩家。 */
const TARGET_RANGE = 40;

/** boss 弹落点的 TNT 数量（一颗弹 3~4 个，一轮 3 弹合计 9~12，弱于爆炸法杖单发 6~8）。 */
const BOSS_TNT_MIN = 3;
const BOSS_TNT_MAX = 4;
/** TNT 撒落半径，与爆炸法杖一致（套用 staffs.js 的撒布算法）。 */
const BOSS_TNT_SPREAD_RADIUS = 5.5;

/** 冰弹命中后的冻结范围与效果。 */
const ICE_FREEZE_RADIUS = 5;
const ICE_SLOW_SECONDS = 5;

/** 落地冲击波：半径 6、伤害 16（≥15）、水平击飞 1.4。 */
const SHOCKWAVE_RADIUS = 6;
const SHOCKWAVE_DAMAGE = 16;
const SHOCKWAVE_KNOCKBACK = 1.4;

/** 冥想爆发：找最近至多 3 名玩家，各自半径 4 内 18 伤害爆炸冲击。 */
const BOOM_RANGE = 16;
const BOOM_TARGETS = 3;
const BOOM_RADIUS = 4;
const BOOM_DAMAGE = 18;
/** 冥想爆发的凋零/黑暗半径。 */
const BOOM_AURA_RADIUS = 12;

/** 起飞上升速度（格/tick，脚本每 2 tick 重写一次竖直速度）。 */
const ASCENT_SPEED = 0.3;
/** 起飞上升阶段最长持续时间（tick）。 */
const ASCENT_MAX_TICKS = 6 * TicksPerSecond;

const PARTICLE_RING = "minecraft:totem_particle";
const PARTICLE_ROAR = "minecraft:knockback_roar_particle";
const PARTICLE_SNOW = "pog:snow_effect";

// ---------------------------------------------------------------------------
// 工具函数（与 staffs.js 同款写法）
// ---------------------------------------------------------------------------

/** 兼容 isValid 属性 / 方法两种形态。 */
function isAlive(entity) {
    if (!entity) return false;
    try {
        const value = entity.isValid;
        return typeof value === "function" ? value.call(entity) : value === true;
    } catch {
        return false;
    }
}

/** 重设弹体速度：先清空再施加，弹道完全可预测。 */
function setBallVelocity(ball, velocity) {
    try {
        ball.clearVelocity();
        ball.applyImpulse(velocity);
    } catch {
        // 弹体已消失，忽略
    }
}

/** 登记投掷物主人：子弹不会和 boss 自己碰撞。 */
function setProjectileOwner(entity, owner) {
    try {
        const projectile = entity.getComponent(PROJECTILE_COMPONENT);
        if (projectile) projectile.owner = owner;
    } catch {
        // 没有 projectile 组件时忽略
    }
}

/**
 * boss 的索敌：只锁玩家（半径 40 内最近）。
 * 不做任何实体全量扫描 —— 天然绕开悬浮名牌/特效火焰这类假目标问题。
 */
function findBossTarget(from, range) {
    let players;
    try {
        players = from.dimension.getPlayers({
            location: from.location,
            maxDistance: range,
        });
    } catch {
        return undefined;
    }

    let best;
    let bestDist = Infinity;
    for (const player of players) {
        const dx = player.location.x - from.location.x;
        const dy = player.location.y - from.location.y;
        const dz = player.location.z - from.location.z;
        const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
        if (dist < bestDist) {
            bestDist = dist;
            best = player;
        }
    }
    return best;
}

/** boss 是否处于红血（void 皮肤）阶段 —— 由 BP 的 environment_sensor 切皮肤。 */
function isEnraged(boss) {
    try {
        return boss.getProperty("lucky:skin") === "void";
    } catch {
        return false;
    }
}

/** 在落点周围均匀撒一拨“即将爆炸”的 TNT（套用 staffs.js 的 from_explosion 分组写法）。 */
function spawnTntBarrage(dimension, origin, countMin, countMax) {
    const count = countMin + Math.floor(Math.random() * (countMax - countMin + 1));
    for (let i = 0; i < count; i++) {
        const angle = Math.random() * Math.PI * 2;
        // 开方采样，让落点在圆面内均匀分布
        const distance = Math.sqrt(Math.random()) * BOSS_TNT_SPREAD_RADIUS;
        const x = (origin.x + Math.cos(angle) * distance).toFixed(2);
        const y = (origin.y + 1).toFixed(2);
        const z = (origin.z + Math.sin(angle) * distance).toFixed(2);
        try {
            dimension.runCommand(`summon tnt ${x} ${y} ${z} ~ ~ from_explosion`);
        } catch {
            // 区块未加载等情况忽略这一个
        }
    }
    try {
        dimension.playSound("random.fuse", origin);
    } catch {
        // 忽略
    }
}

/** 以某点为中心铺一圈粒子。 */
function spawnParticleRing(dimension, center, radius, count, particleId) {
    for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        try {
            dimension.spawnParticle(particleId, {
                x: center.x + Math.cos(angle) * radius,
                y: center.y + 0.5,
                z: center.z + Math.sin(angle) * radius,
            });
        } catch {
            // 单个粒子失败忽略
        }
    }
}

