// ---------------------------------------------------------------------------
// 天空阶段：属性行三连弹（参照原模组 gold/soul/illusion orb burst）
// ---------------------------------------------------------------------------

/** 一轮属性行的弹数（原模组 burst_shots 3）。 */
const ORB_COUNT = 3;
/** 相邻两发属性行的间隔（原模组 burst_interval 0.7 秒 ≈ 14 tick，取 10 tick 更紧凑）。 */
const ORB_GAP_TICKS = 10;
/** 属性行的飞行速率（格/tick），比追踪弹快，直线弹道。 */
const ORB_SPEED = 1.3;
/** 出手方向的随机散布（弧度近似，按速度向量分量扰动）。 */
const ORB_SPREAD = 0.12;

/**
 * 属性行三连弹：原模组的招牌攻击——三颗小弹快速连射、直线飞行不追踪。
 * 命中 10 伤害 + 击退（BP impact_damage），命中方块/生物或 3 秒超时后自灭
 * （BP definition_event → instant_despawn，无需脚本收尾）。
 * 弹体不可被玩家打掉（原模组 orb 即不可摧毁）。
 */
function fireOrbBurst(boss) {
    for (let i = 0; i < ORB_COUNT; i++) {
        system.runTimeout(() => {
            if (!isAlive(boss)) return;
            const target = findBossTarget(boss, TARGET_RANGE);
            if (!target) return;

            const head = boss.getHeadLocation();
            let dx = target.location.x - head.x;
            let dy = target.location.y + 1 - head.y;
            let dz = target.location.z - head.z;
            // 小幅随机散布：三发不会完全叠在一起
            dx += (Math.random() - 0.5) * 2 * ORB_SPREAD * ORB_SPEED;
            dy += (Math.random() - 0.5) * 2 * ORB_SPREAD * ORB_SPEED;
            dz += (Math.random() - 0.5) * 2 * ORB_SPREAD * ORB_SPEED;
            const len = Math.sqrt(dx * dx + dy * dy + dz * dz) || 1;
            const dir = { x: dx / len, y: dy / len, z: dz / len };

            let orb;
            try {
                orb = boss.dimension.spawnEntity("lucky:boss_orb", {
                    x: head.x + dir.x * 1.6,
                    y: head.y + dir.y * 1.6,
                    z: head.z + dir.z * 1.6,
                });
            } catch {
                return;
            }
            setProjectileOwner(orb, boss);
            setBallVelocity(orb, {
                x: dir.x * ORB_SPEED,
                y: dir.y * ORB_SPEED,
                z: dir.z * ORB_SPEED,
            });
            try {
                boss.dimension.playSound("lucky.unseeker_boss.attack_1", head);
            } catch {
                // 忽略
            }
        }, i * ORB_GAP_TICKS);
    }
}

// ---------------------------------------------------------------------------
// 天空阶段：灵魂风暴（参照原模组 void_attack 的凋零领域）
// ---------------------------------------------------------------------------

/** 灵魂风暴的作用半径（原模组 void_attack effect_range 10，略放大到 12）。 */
const STORM_RADIUS = 12;
/** 凋零持续秒数（原模组 effect_time 5）。 */
const STORM_WITHER_SECONDS = 5;
/** 减速持续秒数。 */
const STORM_SLOW_SECONDS = 3;

/**
 * 灵魂风暴：boss 结印，把周围 12 格内的玩家拖入凋零+减速，
 * 配双层灵魂火焰粒子环。不发射弹体——专门惩罚站在 boss 正下方挂机的打法。
 */
function handleSoulStorm(boss) {
    const dimension = boss.dimension;
    let at;
    try {
        at = boss.location;
    } catch {
        return;
    }

    try {
        spawnParticleRing(dimension, at, 3, 12, "lucky:unseeker.blue_flame");
        spawnParticleRing(dimension, at, STORM_RADIUS * 0.7, 20, "lucky:unseeker.gray_flame");
        spawnParticleRing(dimension, at, STORM_RADIUS, 16, PARTICLE_RING);
        dimension.playSound("lucky.unseeker_boss.meditation", at);
    } catch {
        // 视听失败不影响判定
    }

    try {
        for (const player of dimension.getPlayers({
            location: at,
            maxDistance: STORM_RADIUS,
        })) {
            player.addEffect("wither", STORM_WITHER_SECONDS * TicksPerSecond, {
                amplifier: 0,
                showParticles: false,
            });
            player.addEffect("slowness", STORM_SLOW_SECONDS * TicksPerSecond, {
                amplifier: 2,
                showParticles: true,
            });
        }
    } catch {
        // 玩家查询失败忽略
    }
