/**
 * 发射一颗潜影贝级强追踪弹：boss 头部前方 1.6 格出手，
 * 出手即锁定最近玩家，之后每 2 tick 重写速度（方向朝目标混合、速率恒定、无重力）。
 * @param kind "bomb" | "ice"
 */
function launchHomingBullet(boss, kind) {
    const speed = kind === "bomb" ? BULLET_SPEED_BOMB : BULLET_SPEED_ICE;
    const head = boss.getHeadLocation();
    let target = findBossTarget(boss, TARGET_RANGE);
    if (!target) return;

    const to = {
        x: target.location.x - head.x,
        y: target.location.y + 1 - head.y,
        z: target.location.z - head.z,
    };
    const len = Math.sqrt(to.x * to.x + to.y * to.y + to.z * to.z) || 1;
    const dir = { x: to.x / len, y: to.y / len, z: to.z / len };

    let bullet;
    try {
        bullet = boss.dimension.spawnEntity(
            kind === "bomb" ? BOMB_BULLET : ICE_BULLET,
            {
                x: head.x + dir.x * 1.6,
                y: head.y + dir.y * 1.6,
                z: head.z + dir.z * 1.6,
            },
        );
    } catch {
        return;
    }

    setProjectileOwner(bullet, boss);

    let velocity = { x: dir.x * speed, y: dir.y * speed, z: dir.z * speed };
    setBallVelocity(bullet, velocity);

    let ticks = 0;
    let lastPos = bullet.location;
    const runId = system.runInterval(() => {
        if (!isAlive(bullet)) {
            system.clearRun(runId);
            try {
                bulletTrackers.delete(bullet.id);
            } catch {
                // 实体已失效，直接清理
            }
            finishBossBullet(kind, bullet, lastPos);
            return;
        }
        ticks += 2;

        try {
            lastPos = bullet.location;
        } catch {
            // 读不到就沿用上一次坐标
        }

        if (ticks <= BULLET_HOMING_TICKS) {
            if (!isAlive(target)) {
                // 目标下线/死亡就换成离弹最近的玩家；没有玩家则直飞
                target = findBossTarget(bullet, TARGET_RANGE);
            }
            if (isAlive(target)) {
                try {
                    const from = bullet.location;
                    const tx = target.location.x - from.x;
                    const ty = target.location.y + 1 - from.y;
                    const tz = target.location.z - from.z;
                    const dist = Math.sqrt(tx * tx + ty * ty + tz * tz);
                    if (dist > 0.001) {
                        // 速度方向朝目标方向混合 BULLET_STEER，速率保持不变
                        let mx = velocity.x * (1 - BULLET_STEER) + (tx / dist) * speed * BULLET_STEER;
                        let my = velocity.y * (1 - BULLET_STEER) + (ty / dist) * speed * BULLET_STEER;
                        let mz = velocity.z * (1 - BULLET_STEER) + (tz / dist) * speed * BULLET_STEER;
                        const ms = Math.sqrt(mx * mx + my * my + mz * mz) || 1;
                        velocity = {
                            x: (mx / ms) * speed,
                            y: (my / ms) * speed,
                            z: (mz / ms) * speed,
                        };
                    }
                } catch {
                    // 弹体或目标刚好消失，忽略
                }
            }
        }

        setBallVelocity(bullet, velocity);
    }, 2);

    try {
        bulletTrackers.set(bullet.id, runId);
    } catch {
        // 实体已消失，循环会自行退出
    }
}
